import json,hashlib
from pathlib import Path
from collections import Counter

def main():
 out=Path('audits/20261109/counters');c=json.loads((out/'consistency.json').read_text(encoding='utf-8'));o=json.loads((out/'ocr_comparison.json').read_text(encoding='utf-8'));m=json.loads((out/'manual_review.json').read_text(encoding='utf-8'));d=json.loads(Path('assets/counters/unit_definitions.json').read_text(encoding='utf-8'))['definitions'];catalog=json.loads(Path('assets/counters/counter_catalog.json').read_text(encoding='utf-8'))
 scanned={z['type_id'] for z in o['rows'] if z['face']=='front' and z['matched']};manual={z['type_id'] for z in m['entries']};coverage=len(scanned|manual)
 c['catalog_image_paths']=len(set(catalog['images'].values()));c['catalog_missing_image_paths']=[p for p in set(catalog['images'].values()) if not Path(p).is_file()];c['catalog_ids_without_definition']=sorted(set(catalog['counter_types'])-set(d));(out/'consistency.json').write_text(json.dumps(c,indent=2,ensure_ascii=False),encoding='utf-8')
 lines=['# Counter audit — started 2026-11-09, completed 2026-11-10','', '**Read-only proposals. No catalog, saved definitions, status or artwork changed.**','',f'Current inventory: **{c["definitions"]:,} definitions; {o["completed"]:,} Verified / 1,260 In progress**. Previous prose notes are historical claims, not the current-file inventory.','', '## Coverage and evidence','',f'- Automated structural/completeness audit: **all 6,968 definitions**, including all 5,708 completed entries. No duplicate JSON keys, no missing catalog IDs, all 9,696 imported artwork paths exist; assigned artwork is readable and recorded hashes agree. All 5,708 completed entries pass existing editor completeness checks. The 33 missing assigned-front flags concern In progress placeholders, not completed entries.','- Fresh original-art OCR: **9,454 face images**, covering every completed front and assigned printed reverse. OCR panels contain original pixels only; expected metadata is never rendered into the OCR inputs. Contrast-normalized strips are a second pixel view, not a second catalog. Windows OCR independently transcribes them before comparison.',f'- **{len(scanned):,} / 5,708 ({len(scanned)/5708:.1%})** completed entries have a matching front literal printed-factor sequence/code from fresh OCR. This establishes only the named factor field, not a fully verified entry. All failures remain unresolved OCR, not proposed corrections.',f'- **120 entries (2.1%) manually inspected** in 20 stratified batches, spanning {len(m["by_nationality"])} nationalities, all five completed counter categories and 73 nationality/category/ground-format strata. Front and assigned reverse original art compared for visible designation, symbol, size/status and printed factors. Physical crops compared where direct source locators exist. **{coverage:,} unique completed IDs** have at least a manual-art or matching-factor check; these counts overlap.', '- **Full independent metadata/physical verification of a majority has NOT been achieved.** Majority coverage here is automated factor corroboration only. Nationality/service for every entry, all tiny modifiers, and correct physical-front/reverse relationships across most entries remain unverified. A prior confidence number or generated review file is not independent evidence.','', '## Confirmed source-locator errors','', 'These are corroboration/provenance errors: current physical locations point to other counters. They do not by themselves prove that the saved digital ratings are wrong. The nine cases were also re-extracted directly from the original PDF embedded images, using the existing sheet geometry and surrounding cells, rather than relying solely on cached crops. Proposed correction: replace or withdraw the incorrect physical corroboration claim and find the exact cell. Preserve current art/ratings until that review.','', '| ID | Current claim / source | Observed problem | Proposed correction |','| --- | --- | --- | --- |']
 for z in m['findings']:
  if z['kind']!='confirmed_locator_mismatch':continue
  e=z['current'];lines.append(f"| {z['type_id']} | {Path(e['source_pdf']).name}, PDF p{e['front_page']}, r{e['front_row']} c{e['front_column']}: {e['result']} | {z['detail']} | Correct source locator; re-establish physical pair/blank evidence. |")
 lines+=['','## Ambiguous or unreadable source evidence','','| ID | Current value | Uncertainty | Proposed action |','| --- | --- | --- | --- |']
 for z in m['findings']:
  if z['kind']=='ambiguous_source_crop':lines.append(f"| {z['type_id']} | {z['current'].get('result')} | {z['detail']} | Inspect uncropped physical front/back with neighboring context; no automatic correction. |")
 lines+=['', 'No confirmed numeric-factor transcription error was found in the manual sample. OCR mismatches are exported individually with expected and observed text in `ocr_comparison.json`; they are NOT confirmed data errors. Seven shared front-art groups and eleven nonreciprocal link groups are listed in `consistency.json`; duplicated appearances and physical variants can make these legitimate. No ID merge or reciprocal rewrite is proposed solely from this check.','', '## Fields checked by automated artwork reading','','| Category | Completed fronts attempted | Matching printed field | Field scope |','| --- | --- | --- | --- |']
 for category,v in o['categories'].items():
  if not v['fronts_attempted']:continue
  field='core bottom ratings or printed level/code' if category=='Ground unit' else 'top attack/code/defense' if category=='Air unit' else 'top gunnery/code/protection' if category=='Naval unit' else 'manual sample only; automated text not counted as corroborated'
  lines.append(f"| {category} | {v['fronts_attempted']} | {v['fronts_matched']} | {field} |")
 lines+=['', 'A single movement/level field is weaker evidence than a full three-factor line. Per-entry `field`, `expected`, `observed`, image path and image SHA-256 make that distinction reviewable. No OCR score is treated as >95% certainty.','', '## Available references and what is still needed','', '- Six KIC PDFs are locally accessible: Documents **108 (10 pages), 120 (10), 132 (10), 185 (10), 199 (12), 2262 (3)**. Source hashes and paths are recorded in consistency.json. No new LW sheet photos were supplied; original digital LW artwork remains available, but physical-sheet corroboration needs those front/back scans.','- UICFB (both copies), General Charts v1.6, production rules 1.6a/1.6 and six order-of-battle/reference PDFs are locally available. UICFB pp1–3 supplies symbol/size/palette references; source scans supersede prior generated audit prose as physical evidence.','- To resolve locator failures, the existing scans need exact sheet/cell re-identification with uncropped front/back context; no additional photo is necessarily needed. Where the sheet/version is genuinely missing or unreadable, ask for a clearer front/back image with sheet identity.','- All-entry historical nationality/organization verification would additionally need applicable scenario/order-of-battle references, rather than inferring it from art names. Counter metadata and gameplay rules remain distinct.','', '## Reproduce','', 'From the repository root, using the existing virtual environment:','', '```powershell', '.venv/Scripts/python.exe -m audit_tools.counters', '0..3 | ForEach-Object { powershell -NoProfile -File audit_tools/ocr_artwork.ps1 -Jobs "audits/20261109/counters/jobs-$_.json" }', '.venv/Scripts/python.exe -m audit_tools.ocr_factors', '0..3 | ForEach-Object { powershell -NoProfile -File audit_tools/ocr_artwork.ps1 -Jobs "audits/20261109/counters/factor-jobs-$_.json" }', '.venv/Scripts/python.exe -m audit_tools.summarize_counter_ocr', '```','', 'The Python scripts prepare and compare original-pixel inputs. The small PowerShell helper only calls Windows’ built-in OCR API because no Python OCR library is installed; training and analysis remain Python. It does not download a model or change catalog data. OCR output is cached per image panel; use a fresh output directory when source inputs change (the default folder records this run). Manual findings are dated review observations, not automatically repeatable judgments.','', 'Evidence: [manual selection and findings](manual_review.json), [fresh OCR comparison](ocr_comparison.json), [consistency checks](consistency.json). Contact sheets: manual/batch-01.png through batch-20.png; direct PDF locator proof: manual/direct-pdf-locator-checks.png.','']
 (out/'REPORT.md').write_text('\n'.join(lines),encoding='utf-8')
 for p,h in c['protected_sha256'].items():assert hashlib.sha256(Path(p).read_bytes()).hexdigest()==h,p
 print('Counter report written; protected data unchanged. Factor corroboration',len(scanned),'manual',len(manual),'union',coverage)
if __name__=='__main__':main()
